window.AP_CSP_DECKS = [{"id":"apcsp-unit-1","name":"AP Computer Science Principles · Big Idea 1","shortName":"Big Idea 1: Creative Development","builtIn":true,"sourceTitle":"AP CSP Vocabulary List — APCSExamPrep.com","sourceUrl":"https://www.apcsexamprep.com/products/ap-csp-vocabulary-list-pdf","cards":[{"id":"apcsp-unit-1-c1","front":"Abstraction","back":"Simplifying complex systems by focusing on high-level details and hiding lower-level implementation."},{"id":"apcsp-unit-1-c2","front":"Algorithm","back":"A finite set of instructions that accomplish a specific task."},{"id":"apcsp-unit-1-c3","front":"Bias","back":"A systematic error in design, data, or reasoning that skews results or decisions."},{"id":"apcsp-unit-1-c4","front":"Code Segment","back":"A collection of program statements that is part of a program."},{"id":"apcsp-unit-1-c5","front":"Collaboration","back":"Working with others to develop a program; reduces bias and expands perspective."},{"id":"apcsp-unit-1-c6","front":"Computational Artifact","back":"Something created by a human using a computing device (image, audio, video, program, etc.)."},{"id":"apcsp-unit-1-c7","front":"Comment","back":"Non-executed text in code that explains or documents the program for human readers."},{"id":"apcsp-unit-1-c8","front":"Debugging","back":"Finding and fixing errors (bugs) in a program."},{"id":"apcsp-unit-1-c9","front":"Documentation","back":"Written descriptions in a program that explain what the code does."},{"id":"apcsp-unit-1-c10","front":"Incremental Development","back":"Building a program in small pieces, testing each piece before adding more."},{"id":"apcsp-unit-1-c11","front":"Iterative Development","back":"Repeatedly revisiting and refining a program through multiple development cycles."},{"id":"apcsp-unit-1-c12","front":"Program","back":"A collection of program statements that performs a specific task when run by a computer."},{"id":"apcsp-unit-1-c13","front":"Program Development","back":"The full process of creating a program: designing, writing, testing, and debugging."},{"id":"apcsp-unit-1-c14","front":"Prototype","back":"An early version of a program used to test ideas before building the full solution."},{"id":"apcsp-unit-1-c15","front":"Requirements","back":"Descriptions of what a program must do; constraints that the solution must satisfy."},{"id":"apcsp-unit-1-c16","front":"Testing","back":"Running a program with various inputs to verify it behaves correctly."},{"id":"apcsp-unit-1-c17","front":"User","back":"A person who uses a program and interacts with its interface."},{"id":"apcsp-unit-1-c18","front":"Modularity","back":"Breaking a program into smaller, self-contained pieces (procedures/modules) that can be developed independently."},{"id":"apcsp-unit-1-c19","front":"Procedural Abstraction","back":"Using a named procedure to hide implementation details; you know WHAT it does, not HOW."},{"id":"apcsp-unit-1-c20","front":"Expected Behavior","back":"The output or result a program should produce for a given input, as defined by requirements."}],"questions":[],"feynmanPrompts":[{"id":"apcsp-unit-1-f1","prompt":"Program development process"},{"id":"apcsp-unit-1-f2","prompt":"Abstraction and modularity"},{"id":"apcsp-unit-1-f3","prompt":"Testing, debugging, and iteration"}]},{"id":"apcsp-unit-2","name":"AP Computer Science Principles · Big Idea 2","shortName":"Big Idea 2: Data","builtIn":true,"sourceTitle":"AP CSP Vocabulary List — APCSExamPrep.com","sourceUrl":"https://www.apcsexamprep.com/products/ap-csp-vocabulary-list-pdf","cards":[{"id":"apcsp-unit-2-c1","front":"Analog Data","back":"Data measured on a continuous scale (e.g., sound waves, temperature)."},{"id":"apcsp-unit-2-c2","front":"Binary","back":"A base-2 number system using only 0 and 1; the foundation of all digital data."},{"id":"apcsp-unit-2-c3","front":"Bit","back":"The smallest unit of digital data; a single binary digit (0 or 1)."},{"id":"apcsp-unit-2-c4","front":"Byte","back":"8 bits; can represent 256 distinct values (2^8)."},{"id":"apcsp-unit-2-c5","front":"Clean Data","back":"Data that has been checked and corrected for accuracy, completeness, and consistency."},{"id":"apcsp-unit-2-c6","front":"Cleaning Data","back":"The process of removing errors, inconsistencies, or irrelevant data from a dataset."},{"id":"apcsp-unit-2-c7","front":"Compression","back":"Reducing the size of data to save storage or speed up transmission."},{"id":"apcsp-unit-2-c8","front":"Data","back":"Information in a form that can be processed by a computer."},{"id":"apcsp-unit-2-c9","front":"Data Set","back":"A collection of related data, often organized in a table with rows and columns."},{"id":"apcsp-unit-2-c10","front":"Digital Data","back":"Data represented as discrete values (0s and 1s)."},{"id":"apcsp-unit-2-c11","front":"Filtering Data","back":"Selecting a subset of data that meets specific criteria."},{"id":"apcsp-unit-2-c12","front":"Lossless Compression","back":"Compression that allows the original data to be perfectly reconstructed (e.g., ZIP, PNG)."},{"id":"apcsp-unit-2-c13","front":"Lossy Compression","back":"Compression that permanently removes some data to achieve a smaller file size (e.g., MP3, JPEG)."},{"id":"apcsp-unit-2-c14","front":"Metadata","back":"Data that describes other data (e.g., file size, creation date, author)."},{"id":"apcsp-unit-2-c15","front":"Overflow Error","back":"An error that occurs when a computed value exceeds the storage capacity of its data type."},{"id":"apcsp-unit-2-c16","front":"Pattern","back":"A repeated or regular arrangement in data that can reveal trends or relationships."},{"id":"apcsp-unit-2-c17","front":"Roundoff Error","back":"An error caused by the inability to represent a decimal exactly in binary floating point."},{"id":"apcsp-unit-2-c18","front":"Sampling","back":"Collecting data from a subset of a population to represent the whole."},{"id":"apcsp-unit-2-c19","front":"Structured Data","back":"Data organized in a defined format (e.g., spreadsheet, database table)."},{"id":"apcsp-unit-2-c20","front":"Unstructured Data","back":"Data without a predefined format (e.g., text documents, images, social media posts)."},{"id":"apcsp-unit-2-c21","front":"Visualization","back":"Representing data graphically (charts, graphs, maps) to reveal patterns or insights."},{"id":"apcsp-unit-2-c22","front":"Collaboration (Data)","back":"Multiple groups or organizations combining datasets to enable richer analysis."},{"id":"apcsp-unit-2-c23","front":"Scalability","back":"The ability of a system to handle growing amounts of data or users."},{"id":"apcsp-unit-2-c24","front":"Problem (Data)","back":"A question or challenge that data analysis aims to answer."},{"id":"apcsp-unit-2-c25","front":"Binary Representation","back":"How all digital data — numbers, text, images, sound — is ultimately stored as 0s and 1s."},{"id":"apcsp-unit-2-c26","front":"Color Representation","back":"Colors stored as RGB triplets: three 8-bit values (0–255) for red, green, and blue channels."}],"questions":[],"feynmanPrompts":[{"id":"apcsp-unit-2-f1","prompt":"Representing information with bits"},{"id":"apcsp-unit-2-f2","prompt":"Lossy and lossless compression"},{"id":"apcsp-unit-2-f3","prompt":"Finding patterns in data"}]},{"id":"apcsp-unit-3","name":"AP Computer Science Principles · Big Idea 3","shortName":"Big Idea 3: Algorithms and Programming","builtIn":true,"sourceTitle":"AP CSP Vocabulary List — APCSExamPrep.com","sourceUrl":"https://www.apcsexamprep.com/products/ap-csp-vocabulary-list-pdf","cards":[{"id":"apcsp-unit-3-c1","front":"AND (Logical)","back":"A Boolean operator that returns TRUE only if both operands are TRUE."},{"id":"apcsp-unit-3-c2","front":"Arithmetic Operators","back":"Operators that perform math: +, -, *, /, MOD (remainder), and integer division."},{"id":"apcsp-unit-3-c3","front":"Assignment","back":"Setting a variable to a value using the left arrow (←) in AP pseudocode."},{"id":"apcsp-unit-3-c4","front":"Boolean Expression","back":"An expression that evaluates to TRUE or FALSE."},{"id":"apcsp-unit-3-c5","front":"Boolean Value","back":"A data type with only two possible values: TRUE or FALSE."},{"id":"apcsp-unit-3-c6","front":"Calling a Procedure","back":"Executing a named block of code (procedure/function) from another part of the program."},{"id":"apcsp-unit-3-c7","front":"Concatenation","back":"Joining two strings together end-to-end."},{"id":"apcsp-unit-3-c8","front":"Conditional","back":"A statement that executes different code based on whether a condition is TRUE or FALSE (IF/ELSE)."},{"id":"apcsp-unit-3-c9","front":"Decision Problem","back":"A problem with a yes-or-no answer; some are undecidable (no algorithm can always solve them)."},{"id":"apcsp-unit-3-c10","front":"Element (List)","back":"A single item in a list, accessed by its index."},{"id":"apcsp-unit-3-c11","front":"FOR EACH Loop","back":"A loop that iterates over every element in a list, one at a time."},{"id":"apcsp-unit-3-c12","front":"Function / Procedure","back":"A named, reusable block of code that performs a specific task."},{"id":"apcsp-unit-3-c13","front":"Heuristic","back":"An approach to a problem that finds a good-enough solution when an optimal one is too costly."},{"id":"apcsp-unit-3-c14","front":"Index","back":"The position of an element in a list; AP CSP lists are 1-indexed (first element = index 1)."},{"id":"apcsp-unit-3-c15","front":"Infinite Loop","back":"A loop that never terminates because its exit condition is never met."},{"id":"apcsp-unit-3-c16","front":"Input","back":"Data provided to a program (keyboard, mouse, file, sensor, etc.)."},{"id":"apcsp-unit-3-c17","front":"Iteration","back":"Repeating a block of code using a loop (REPEAT N TIMES or REPEAT UNTIL)."},{"id":"apcsp-unit-3-c18","front":"Length (List)","back":"The number of elements in a list; accessed via LENGTH(list) in AP pseudocode."},{"id":"apcsp-unit-3-c19","front":"Linear Search","back":"Checking each element of a list one by one until the target is found; works on unsorted data."},{"id":"apcsp-unit-3-c20","front":"List","back":"An ordered, changeable collection of items; AP CSP lists are 1-indexed."},{"id":"apcsp-unit-3-c21","front":"Logic Error","back":"A mistake in the algorithm that causes wrong results without crashing the program."},{"id":"apcsp-unit-3-c22","front":"MOD Operator","back":"Returns the remainder of integer division (17 MOD 5 = 2)."},{"id":"apcsp-unit-3-c23","front":"Nested Conditional","back":"An IF statement inside another IF statement, enabling more complex decision-making."},{"id":"apcsp-unit-3-c24","front":"NOT (Logical)","back":"A Boolean operator that reverses the truth value of an expression."},{"id":"apcsp-unit-3-c25","front":"OR (Logical)","back":"A Boolean operator that returns TRUE if at least one operand is TRUE."},{"id":"apcsp-unit-3-c26","front":"Output","back":"Data a program produces (display, sound, file, network, etc.)."},{"id":"apcsp-unit-3-c27","front":"Parameter","back":"A variable in a procedure definition that receives a value when the procedure is called."},{"id":"apcsp-unit-3-c28","front":"Return Value","back":"The value a function sends back to the calling code after it finishes executing."},{"id":"apcsp-unit-3-c29","front":"Sequencing","back":"Statements execute in the order they appear; the most fundamental program structure."},{"id":"apcsp-unit-3-c30","front":"String","back":"A sequence of characters treated as a single value."},{"id":"apcsp-unit-3-c31","front":"Syntax Error","back":"A mistake that violates the rules of the programming language; prevents the program from running."},{"id":"apcsp-unit-3-c32","front":"Traversal","back":"Processing each element of a list, usually with a loop."},{"id":"apcsp-unit-3-c33","front":"Undecidable Problem","back":"A problem for which no algorithm can always produce a correct yes/no answer (e.g., Halting Problem)."},{"id":"apcsp-unit-3-c34","front":"Variable","back":"A named storage location that holds a value which can change during program execution."},{"id":"apcsp-unit-3-c35","front":"WHILE Loop (REPEAT UNTIL)","back":"A loop that continues until a condition becomes TRUE."},{"id":"apcsp-unit-3-c36","front":"Binary Search","back":"Efficiently finds a target in a SORTED list by repeatedly halving the search space; O(log n)."},{"id":"apcsp-unit-3-c37","front":"Efficiency","back":"How well an algorithm uses time and memory; measured by how runtime grows with input size."}],"questions":[],"feynmanPrompts":[{"id":"apcsp-unit-3-f1","prompt":"Sequencing, selection, and iteration"},{"id":"apcsp-unit-3-f2","prompt":"Lists and data abstraction"},{"id":"apcsp-unit-3-f3","prompt":"Algorithm efficiency and undecidable problems"}]},{"id":"apcsp-unit-4","name":"AP Computer Science Principles · Big Idea 4","shortName":"Big Idea 4: Computing Systems and Networks","builtIn":true,"sourceTitle":"AP CSP Vocabulary List — APCSExamPrep.com","sourceUrl":"https://www.apcsexamprep.com/products/ap-csp-vocabulary-list-pdf","cards":[{"id":"apcsp-unit-4-c1","front":"Bandwidth","back":"The maximum amount of data that can be transmitted over a network in a given time (bits/second)."},{"id":"apcsp-unit-4-c2","front":"Binary Sequence","back":"A sequence of 0s and 1s used to represent all data in computing systems."},{"id":"apcsp-unit-4-c3","front":"Bit Rate","back":"The number of bits transmitted per second over a network connection."},{"id":"apcsp-unit-4-c4","front":"Client","back":"A device or application that requests services or resources from a server."},{"id":"apcsp-unit-4-c5","front":"Cybersecurity","back":"Practices and technologies designed to protect systems, networks, and data from attacks."},{"id":"apcsp-unit-4-c6","front":"Denial of Service (DoS)","back":"An attack that overwhelms a server with requests to make it unavailable to legitimate users."},{"id":"apcsp-unit-4-c7","front":"Encryption","back":"Converting data into a coded form so only authorized parties can read it."},{"id":"apcsp-unit-4-c8","front":"Fault Tolerant","back":"A system that continues to function even when parts of it fail."},{"id":"apcsp-unit-4-c9","front":"Firewall","back":"A security system that monitors and controls incoming/outgoing network traffic based on rules."},{"id":"apcsp-unit-4-c10","front":"Hardware","back":"The physical components of a computer (CPU, RAM, storage, keyboard, etc.)."},{"id":"apcsp-unit-4-c11","front":"HTTP / HTTPS","back":"Protocols for transferring web pages; HTTPS adds encryption for security."},{"id":"apcsp-unit-4-c12","front":"Information Privacy","back":"The right to control how personal data is collected, stored, and shared."},{"id":"apcsp-unit-4-c13","front":"Internet","back":"A global network of interconnected networks communicating using standard protocols (TCP/IP)."},{"id":"apcsp-unit-4-c14","front":"IP Address","back":"A unique numerical label assigned to each device on a network (e.g., 192.168.1.1)."},{"id":"apcsp-unit-4-c15","front":"Latency","back":"The delay between sending a request and receiving a response over a network."},{"id":"apcsp-unit-4-c16","front":"Malware","back":"Malicious software designed to disrupt, damage, or gain unauthorized access to systems."},{"id":"apcsp-unit-4-c17","front":"Network","back":"A group of connected computing devices that can communicate and share resources."},{"id":"apcsp-unit-4-c18","front":"Operating System","back":"Software that manages hardware resources and provides services for programs."},{"id":"apcsp-unit-4-c19","front":"Packet","back":"A small unit of data sent across a network; large messages are broken into packets."},{"id":"apcsp-unit-4-c20","front":"Packet Switching","back":"A method of transmitting data by breaking it into packets that may take different routes."},{"id":"apcsp-unit-4-c21","front":"Parallel Computing","back":"Using multiple processors to solve parts of a problem simultaneously, reducing total time."},{"id":"apcsp-unit-4-c22","front":"Phishing","back":"A social engineering attack using deceptive emails or websites to steal credentials."},{"id":"apcsp-unit-4-c23","front":"Protocol","back":"A set of rules that defines how data is formatted and transmitted between devices."},{"id":"apcsp-unit-4-c24","front":"Router","back":"A networking device that forwards data packets between networks."},{"id":"apcsp-unit-4-c25","front":"Server","back":"A device or software that provides services or resources to clients on a network."},{"id":"apcsp-unit-4-c26","front":"Software","back":"Programs and operating information that tell hardware what to do."},{"id":"apcsp-unit-4-c27","front":"TCP/IP","back":"The fundamental communication protocol suite of the Internet; ensures reliable delivery."},{"id":"apcsp-unit-4-c28","front":"Virus","back":"Malware that attaches itself to legitimate programs and spreads when those programs run."},{"id":"apcsp-unit-4-c29","front":"World Wide Web (WWW)","back":"A system of interlinked hypertext documents accessed via the Internet using HTTP."},{"id":"apcsp-unit-4-c30","front":"Sequential Computing","back":"Tasks are executed one at a time in order; contrasted with parallel computing."},{"id":"apcsp-unit-4-c31","front":"DNS (Domain Name System)","back":"A system that translates human-readable domain names (e.g., google.com) into IP addresses."},{"id":"apcsp-unit-4-c32","front":"Redundancy","back":"Duplicate components in a network so that if one path fails, another can be used — key to fault tolerance."}],"questions":[],"feynmanPrompts":[{"id":"apcsp-unit-4-f1","prompt":"How data travels across the Internet"},{"id":"apcsp-unit-4-f2","prompt":"Fault tolerance and redundancy"},{"id":"apcsp-unit-4-f3","prompt":"Cybersecurity threats and defenses"}]},{"id":"apcsp-unit-5","name":"AP Computer Science Principles · Big Idea 5","shortName":"Big Idea 5: Impact of Computing","builtIn":true,"sourceTitle":"AP CSP Vocabulary List — APCSExamPrep.com","sourceUrl":"https://www.apcsexamprep.com/products/ap-csp-vocabulary-list-pdf","cards":[{"id":"apcsp-unit-5-c1","front":"Accessibility","back":"Designing technology to be usable by people of all abilities, including those with disabilities."},{"id":"apcsp-unit-5-c2","front":"Bias (Computing)","back":"Systematic errors in algorithms or datasets that produce unfair or inaccurate results."},{"id":"apcsp-unit-5-c3","front":"Citizen Science","back":"Research projects where the general public contributes data or analysis."},{"id":"apcsp-unit-5-c4","front":"Collaboration (Impact)","back":"Computers enable global collaboration, allowing distributed teams to work together."},{"id":"apcsp-unit-5-c5","front":"Copyright","back":"Legal protection for original creative works; controls who can copy or distribute them."},{"id":"apcsp-unit-5-c6","front":"Creative Commons","back":"A licensing system allowing creators to share works with specific usage permissions."},{"id":"apcsp-unit-5-c7","front":"Crowdsourcing","back":"Collecting input, ideas, or data from a large group of people, often via the Internet."},{"id":"apcsp-unit-5-c8","front":"Cybercrime","back":"Criminal activity carried out using computers or the Internet."},{"id":"apcsp-unit-5-c9","front":"Data Mining","back":"Analyzing large datasets to discover patterns, correlations, or useful information."},{"id":"apcsp-unit-5-c10","front":"Digital Divide","back":"The gap between those with access to technology/Internet and those without."},{"id":"apcsp-unit-5-c11","front":"Environmental Impact","back":"The effect computing has on energy consumption, e-waste, and carbon emissions."},{"id":"apcsp-unit-5-c12","front":"Ethics","back":"A set of moral principles that guide decisions about right and wrong uses of technology."},{"id":"apcsp-unit-5-c13","front":"Filter Bubble","back":"A state of intellectual isolation caused by algorithms showing users only content they already agree with."},{"id":"apcsp-unit-5-c14","front":"Intellectual Property","back":"Creative works protected by copyright, patents, or trademarks."},{"id":"apcsp-unit-5-c15","front":"Moore's Law","back":"The observation that the number of transistors on a chip roughly doubles every two years."},{"id":"apcsp-unit-5-c16","front":"Open Source","back":"Software whose source code is freely available for anyone to view, modify, and distribute."},{"id":"apcsp-unit-5-c17","front":"Personal Data","back":"Information that can be used to identify an individual (name, email, location, etc.)."},{"id":"apcsp-unit-5-c18","front":"Privacy","back":"The ability of individuals to control what personal information is shared and with whom."},{"id":"apcsp-unit-5-c19","front":"Search Algorithm","back":"An algorithm used by search engines to rank and retrieve web pages (e.g., PageRank)."},{"id":"apcsp-unit-5-c20","front":"Security","back":"Measures taken to protect data and systems from unauthorized access or damage."},{"id":"apcsp-unit-5-c21","front":"Surveillance","back":"Monitoring of individuals or groups, often using computing technology."},{"id":"apcsp-unit-5-c22","front":"Targeted Advertising","back":"Using personal data to serve advertisements specifically tailored to individual users."},{"id":"apcsp-unit-5-c23","front":"Terms of Service","back":"Legal agreements users accept when using software or online services."},{"id":"apcsp-unit-5-c24","front":"Unintended Consequences","back":"Unexpected negative outcomes of a computing innovation not foreseen by its creators."},{"id":"apcsp-unit-5-c25","front":"Dopamine Loop","back":"A feedback cycle in which technology use triggers reward responses, encouraging continued engagement."},{"id":"apcsp-unit-5-c26","front":"Legal Issue","back":"Questions of law related to computing: copyright infringement, privacy violations, hacking laws."},{"id":"apcsp-unit-5-c27","front":"Vishing","back":"Voice phishing — using phone calls to trick victims into revealing personal information."},{"id":"apcsp-unit-5-c28","front":"Computing Innovation","back":"An innovation that uses a program as an integral part of its function (apps, self-driving cars, etc.)."},{"id":"apcsp-unit-5-c29","front":"Disinformation","back":"False information deliberately spread to deceive; computing enables rapid large-scale distribution."},{"id":"apcsp-unit-5-c30","front":"Automation","back":"Using computers to perform tasks that previously required human effort."}],"questions":[],"feynmanPrompts":[{"id":"apcsp-unit-5-f1","prompt":"Benefits and harms of computing innovations"},{"id":"apcsp-unit-5-f2","prompt":"Privacy, bias, and the digital divide"},{"id":"apcsp-unit-5-f3","prompt":"Intellectual property and responsible computing"}]}];
